# gt has no mask: one tab_style() for each text column does the same
Reduce(
  function(tbl, col) {
    tab_style(tbl,
      cell_fill("yellow"),
      cells_body(columns = all_of(col), rows = grepl("p", small_exibble[[col]]))
    )
  },
  names(small_exibble)[sapply(small_exibble, is.character)],
  gt(small_exibble)
)
